<!doctype html><html><head><meta charset="utf-8"><style>
@page{margin:28px 34px}body{font-family:DejaVu Sans,sans-serif;color:#252a31;font-size:11px}.head{border-bottom:4px solid #1683c5;padding-bottom:12px;margin-bottom:18px}.name{font-size:24px;font-weight:bold;color:#163c5c}.sub{color:#557080}.photo{float:right;width:95px;height:115px;object-fit:cover;border:2px solid #1683c5}.section{margin:14px 0}.title{font-size:13px;font-weight:bold;color:#1683c5;border-bottom:1px solid #1683c5;padding-bottom:4px;margin-bottom:7px}.row{margin:4px 0}.label{font-weight:bold;color:#4b5c68}.col{display:inline-block;width:48%;vertical-align:top}.clear{clear:both}
</style></head><body>
<div class="head"><?php if($photoData): ?><img class="photo" src="<?php echo e($photoData); ?>"><?php endif; ?><div class="name"><?php echo e($holder?->full_name ?? 'Candidate'); ?></div><div class="sub">Curriculum Vitae · <?php echo e($recruitment->tracking_number); ?></div><div class="row"><?php echo e($holder?->phone); ?> <?php if($holder?->email): ?> · <?php echo e($holder->email); ?> <?php endif; ?></div><div class="row"><?php echo e($holder?->present_address); ?></div></div>
<div class="section"><div class="title">PERSONAL INFORMATION</div><div class="col"><div class="row"><span class="label">Date of birth:</span> <?php echo e($holder?->dob?->format('d M Y') ?? '—'); ?></div><div class="row"><span class="label">Gender:</span> <?php echo e(ucfirst($holder?->gender ?? '—')); ?></div><div class="row"><span class="label">Nationality:</span> <?php echo e($holder?->nationality ?? '—'); ?></div></div><div class="col"><div class="row"><span class="label">Passport no:</span> <?php echo e($holder?->passport_number ?? '—'); ?></div><div class="row"><span class="label">Passport expiry:</span> <?php echo e($holder?->passport_expiry_date?->format('d M Y') ?? '—'); ?></div><div class="row"><span class="label">Religion / marital status:</span> <?php echo e($holder?->religion ?? '—'); ?> / <?php echo e($holder?->marital_status ?? '—'); ?></div></div><div class="clear"></div></div>
<div class="section"><div class="title">CAREER PROFILE</div><div><?php echo e($recruitment->remarks ?: 'Candidate registered for overseas employment.'); ?></div><div class="row"><span class="label">Applying position:</span> <?php echo e($recruitment->position?->title ?? '—'); ?> · <span class="label">Destination:</span> <?php echo e($recruitment->country?->name ?? '—'); ?></div></div>
<div class="section"><div class="title">EDUCATION</div><div class="row"><span class="label">Education:</span> <?php echo e($recruitment->education_type ?? '—'); ?> <?php echo e($recruitment->education_degree); ?></div><div class="row"><span class="label">Institution:</span> <?php echo e($recruitment->education_school ?? '—'); ?></div><div class="row"><span class="label">Year / grade:</span> <?php echo e($recruitment->education_year ?? '—'); ?> / <?php echo e($recruitment->education_grade ?? '—'); ?></div></div>
<div class="section"><div class="title">EXPERIENCE & SKILLS</div><div class="row"><span class="label">Local experience:</span> <?php echo e($recruitment->local_experience_years ?? '—'); ?> years</div><div class="row"><span class="label">Language proficiency:</span> <?php echo e(is_array($recruitment->language_proficiency) ? implode(', ', $recruitment->language_proficiency) : ($recruitment->language_proficiency ?? '—')); ?></div></div>
<div class="section"><div class="title">REGISTRATION</div><div class="row"><span class="label">Agent:</span> <?php echo e($recruitment->agent?->name ?? '—'); ?> · <span class="label">Company:</span> <?php echo e($recruitment->company?->name ?? '—'); ?></div><div class="row"><span class="label">Tracking number:</span> <?php echo e($recruitment->tracking_number); ?></div></div>
</body></html>
